import {Base,fmt,svgEl} from './base.js';import{clamp,dist,roots,intersection,statistics}from'../math.js';
export default class Graph extends Base{
 constructor(host,ctx){super(host,ctx);this.id=ctx.chapter.id;this.mode=ctx.scene.id;this.points=[[-3,2],[3,-2]];this.playing=false;this.speed=1;this.counts=[];this.total=0;this.pending=0;this.last=0;
 if(this.id===1){this.points=[[1,0]];this.slider('value','Value','मान',-8,8,1,.01);this.button('Next construction step →','अगला रचना चरण →',()=>this.step=(this.step+1)%5)}
 if(this.id===2){for(let[k,v]of Object.entries({a:0,b:1,c:0,d:-4}))this.slider(k,k,k,-5,5,v,.1);}
 if(this.id===3){this.button('Clear points','बिंदु हटाएँ',()=>this.points=[]);this.points=[[-3,2],[3,-2]]}
 if(this.id===4){for(let[k,v]of Object.entries({a:1,b:1,c:-3}))this.slider(k,k,k,-6,6,v,.25);this.select('lines',{label:'Line mode | रेखा प्रकार',items:[['one','One line','1 रेखा'],['two','Two lines (enrichment)','2 रेखाएँ (अतिरिक्त)']]},this.mode==='intersection'?'two':'one');this.second=[];for(let[k,v]of Object.entries({A:1,B:-1,C:1}))this.second.push(this.slider(k,k+' (line 2)',k+' (रेखा 2)',-6,6,v,.25));this.second.forEach(e=>e.hidden=this.lines==='one')}
 if(this.id===14){this.rows=[[1,2],[2,4],[3,6],[4,3],[5,1]];this.select('chart',{label:'Chart type | आलेख प्रकार',items:[['bar','Bar chart + exact statistics','दंड आलेख + सटीक आँकड़े'],['hist','Histogram (equal-width classes)','आयतचित्र (समान चौड़ाई वर्ग)']]},this.mode==='histogram'?'hist':'bar');this.slider('width','Class width','वर्ग चौड़ाई',.5,3,1,.5);let wrap=document.createElement('div');wrap.style.gridColumn='1 / -1';wrap.innerHTML=`<table class="freqTable"><thead><tr><th>${ctx.t('Value / lower boundary','मान / निचली सीमा')}</th><th>${ctx.t('Frequency','बारंबारता')}</th></tr></thead><tbody>${this.rows.map(([x,f],i)=>`<tr><td><input type="number" step="any" value="${x}" data-row="${i}" data-col="0" aria-label="Value ${i+1} | मान ${i+1}"></td><td><input type="number" min="0" max="10000" step="1" value="${f}" data-row="${i}" data-col="1" aria-label="Frequency ${i+1} | बारंबारता ${i+1}"></td></tr>`).join('')}</tbody></table>`;this.controls.append(wrap);for(let e of wrap.querySelectorAll('input'))this.listen(e,'input',()=>{this.rows[+e.dataset.row][+e.dataset.col]=e.value===''?NaN:+e.value;this.changed=true;this.draw();ctx.onChange?.()})}
 if(this.id===15){this.select('device',{label:'Experiment | प्रयोग',items:[['coin','Fair coin','निष्पक्ष सिक्का'],['die','Fair die','निष्पक्ष पासा']]},this.mode==='die'?'die':'coin');this.slider('trials','Number of throws','उछालों की संख्या',10,1000,100,10);this.button('Throw N times','N बार उछालें',()=>{this.pending+=this.trials;this.playing=true;this.last=0;this.tick();ctx.onPlaying?.(true)});this.button('Clear experiment','प्रयोग मिटाएँ',()=>this.clearExperiment());this.clearExperiment()}
 this.draw();}
 clearExperiment(){this.counts=Array(this.device==='die'?6:2).fill(0);this.total=0;this.pending=0;this.draw()}
 update(k){if(this.id===4&&this.second)this.second.forEach(e=>e.hidden=this.lines==='one');if(this.id===1&&k==='value')this.points[0][0]=this.value;if(this.id===15&&k==='device')this.clearExperiment()}
 move(i,p){if(this.id===1){this.value=clamp(p[0],-8,8);this.points[0]=[this.value,0];let input=this.controls.querySelector('input');input.value=this.value;input.previousElementSibling.textContent=fmt(this.value)}else if(this.id===3)this.points[i]=p.map(v=>clamp(v,-8,8))}
 background(p){if(this.id===3&&this.points.length<2){this.points.push(p.map(v=>clamp(v,-8,8)));this.changed=true;this.draw();this.ctx.onChange?.()}}
 tick(){if(this.frame)return;let run=time=>{this.frame=null;if(!this.playing||document.hidden)return;let dt=Math.min(.1,(time-(this.last||time))/1000);this.last=time;this.acc=(this.acc||0)+dt*120*(this.speed||1);let n=Math.min(this.pending,Math.floor(this.acc));this.acc-=n;for(let i=0;i<n;i++){this.counts[Math.floor(Math.random()*this.counts.length)]++;this.total++;this.pending--}if(n&&(!this.ctx.lowpower||!this.lastDraw||time-this.lastDraw>=32||this.pending===0)){this.draw();this.lastDraw=time;this.ctx.onChange?.()}if(this.pending>0)this.frame=requestAnimationFrame(run);else{this.playing=false;this.ctx.onPlaying?.(false)}};this.frame=requestAnimationFrame(run)}
 pause(){this.last=0;this.playing=!this.playing;if(this.playing&&this.pending===0)this.pending=this.trials||100;this.tick();return this.playing}
 draw(){this.clear(this.id!==14&&this.id!==15);let t=this.ctx.t;
 if(this.id===1){this.clear(false);this.cy=230;this.line([-8,0],[8,0],'axis');for(let i=-8;i<=8;i++){this.line([i,-.1],[i,.1],'axis');this.text([i-.1,-.55],i)}this.points[0]=[this.value,0];this.point(this.points[0],0,'P');let out=`P = ${fmt(this.value)}\n${t('Every point represents a real number. Drag P or use arrow keys.','हर बिंदु एक वास्तविक संख्या दर्शाता है। P खींचें या तीर कुंजियाँ दबाएँ।')}`;if(this.mode==='roots'){let a=[0,0],b=[1,0],c=[1,1],d=[1-Math.SQRT1_2,1+Math.SQRT1_2];if(this.step>=1)this.line(a,b);if(this.step>=2)this.line(b,c);if(this.step>=3){this.line(a,c);this.text([.2,1.2],'√2');this.circle(a,Math.SQRT2,'shape',{'stroke-dasharray':'5 5',fill:'none'});this.circle([Math.SQRT2,0],.12,'gold')}if(this.step>=4){this.line(c,d);this.line(a,d);this.circle(a,Math.sqrt(3),'shape',{'stroke-dasharray':'3 5',fill:'none'});this.text([-.7,2.4],'√3');this.circle([Math.sqrt(3),0],.12,'gold')}out=`${t('Step','चरण')} ${this.step} / 4\n`+[t('Start at O = 0.','O = 0 से शुरू करें।'),t('Draw OA = 1 unit.','OA = 1 इकाई बनाएँ।'),t('At A, draw AB = 1 perpendicular to OA.','A पर OA का लंब AB = 1 बनाएँ।'),t('OB = √(1²+1²) = √2. Transfer OB to the number line using an arc.','OB = √(1²+1²) = √2। चाप से OB को संख्या रेखा पर रखें।'),t('At B, draw BC = 1 perpendicular to OB. OC = √(2+1) = √3; transfer OC with an arc.','B पर OB का लंब BC = 1 बनाएँ। OC = √(2+1) = √3; चाप से OC को रेखा पर रखें।')][this.step]+'\n√2 ≈ 1.414; √3 ≈ 1.732'}this.output(out)}
 if(this.id===2){let f=x=>((this.a*x+this.b)*x+this.c)*x+this.d,pts=[];for(let x=-9;x<=9;x+=.025)pts.push([x,clamp(f(x),-20,20)]);this.path(pts,'shape',false,{fill:'none'});let zs=roots(this.a,this.b,this.c,this.d);for(let x of zs)if(Math.abs(x)<9){this.circle([x,0],.15,'gold');this.text([x+.2,.5],fmt(x))}this.output(`p(x) = ${this.a}x³ + ${this.b}x² + ${this.c}x + ${this.d}\n${this.a===0&&this.b===0&&this.c===0?(this.d===0?t('Zero polynomial: every real x is a zero.','शून्य बहुपद: हर वास्तविक x एक शून्यक है।'):t('Nonzero constant: no zeroes.','अशून्य अचर: कोई शून्यक नहीं।')):t('Real zeroes','वास्तविक शून्यक')+': '+(zs.map(fmt).join(', ')||t('none','कोई नहीं'))}`)}
 if(this.id===3){this.points.forEach((p,i)=>this.point(p,i,String.fromCharCode(65+i)));if(this.points.length===2){let[a,b]=this.points,m=[(a[0]+b[0])/2,(a[1]+b[1])/2];this.line(a,b);this.circle(m,.12,'gold');this.text([m[0]+.3,m[1]+.3],'M');this.output(`A(${a.map(fmt)}); B(${b.map(fmt)})\nAB = √[(${fmt(b[0]-a[0])})² + (${fmt(b[1]-a[1])})²] = ${fmt(dist(a,b))}\nM = (${m.map(fmt)})`)}else this.output(t('Click the plane to place up to 2 points.','तल पर क्लिक करके 2 बिंदु रखें।'))}
 if(this.id===4){let drawLine=(a,b,c,cls)=>{if(!a&&!b)return false;if(Math.abs(b)>.001)this.line([-12,(-c+12*a)/b],[12,(-c-12*a)/b],cls);else this.line([-c/a,-10],[-c/a,10],cls);return true},ok=drawLine(this.a,this.b,this.c,'shape'),out=`${this.a}x + ${this.b}y + ${this.c} = 0`;if(!ok)out+='\n'+t(this.c===0?'All points satisfy 0 = 0.':'No point satisfies this equation.',this.c===0?'0 = 0 को सभी बिंदु संतुष्ट करते हैं।':'इस समीकरण को कोई बिंदु संतुष्ट नहीं करता।');if(this.lines==='two'){let ok2=drawLine(this.A,this.B,this.C,'gold');out+=`\n${this.A}x + ${this.B}y + ${this.C} = 0`;if(ok&&ok2){let r=intersection(this.a,this.b,this.c,this.A,this.B,this.C);if(r.type==='point'){this.circle([r.x,r.y],.18,'gold');this.text([r.x+.3,r.y+.3],`(${fmt(r.x)}, ${fmt(r.y)})`);out+=`\n${t('Intersection','प्रतिच्छेद')}: (${fmt(r.x)}, ${fmt(r.y)})`}else out+='\n'+t(r.type==='parallel'?'Parallel: no intersection.':'Coincident: infinitely many common points.',r.type==='parallel'?'समांतर: कोई प्रतिच्छेद नहीं।':'संपाती: अनंत उभयनिष्ठ बिंदु।')}else out+='\n'+t('A zero pair of coefficients does not define a line.','दोनों गुणांक 0 होने पर रेखा निर्धारित नहीं होती।')}this.output(out)}
 if(this.id===14)this.drawStats();if(this.id===15)this.drawProbability();}
 drawStats(){this.clear(false);let t=this.ctx.t,rows=this.rows;if(rows.some(r=>!Number.isFinite(r[0])||Math.abs(r[0])>1000000||!Number.isInteger(r[1])||r[1]<0||r[1]>10000)){this.output(t('Enter values between −1000000 and 1000000 and whole frequencies from 0 to 10000.','−1000000 से 1000000 तक मान और 0 से 10000 तक पूर्णांक बारंबारताएँ भरें।'));return}if(new Set(rows.map(r=>r[0])).size!==rows.length){this.output(t('Use each value / lower boundary only once.','हर मान / निचली सीमा केवल 1 बार लिखें।'));return}let sorted=[...rows].sort((a,b)=>a[0]-b[0]),hist=this.chart==='hist',w=this.width;if(hist&&sorted.some((r,i)=>i&&r[0]<sorted[i-1][0]+w-1e-8)){this.output(t('Histogram classes overlap. Reduce class width or edit boundaries.','आयतचित्र के वर्ग अतिव्यापी हैं। चौड़ाई घटाएँ या सीमाएँ बदलें।'));return}let max=Math.max(1,...rows.map(r=>r[1])),lo=sorted[0][0]-.5,hi=sorted.at(-1)[0]+(hist?w:.5),X=x=>65+(x-lo)/(hi-lo)*470,Y=f=>325-f/max*240;this.svg.append(svgEl('path',{d:'M65 50V325H550',class:'axis',fill:'none'}));for(let k=0;k<=4;k++){this.svg.append(svgEl('text',{x:20,y:Y(max*k/4)+4},fmt(max*k/4)))}for(let[x,f]of sorted){let px=X(x),width=hist?X(x+w)-px:28;this.svg.append(svgEl('rect',{x:hist?px:px-14,y:Y(f),width,height:325-Y(f),fill:'#78d5bc',stroke:'#10352d'}));this.svg.append(svgEl('text',{x:px-5,y:345},fmt(x)))}this.svg.append(svgEl('text',{x:70,y:25},t('Frequency | बारंबारता','Frequency | बारंबारता')));this.svg.append(svgEl('text',{x:180,y:380},t('Value / class boundary | मान / वर्ग सीमा','Value / class boundary | मान / वर्ग सीमा')));let s=statistics(sorted);if(!s){this.output(t('Total frequency is 0. Add observations.','कुल बारंबारता 0 है। प्रेक्षण जोड़ें।'));return}if(!hist){let colors=['#f5c366','#aeb7ff'];[s.mean,s.median].forEach((v,i)=>{let x=X(v);this.svg.append(svgEl('line',{x1:x,x2:x,y1:40,y2:325,stroke:colors[i],'stroke-dasharray':'5 4'}));this.svg.append(svgEl('text',{x:x+4,y:48+i*19,fill:colors[i]},(i?'Median / माध्यक':'Mean / माध्य')+' '+fmt(v)))});for(let m of s.modes)this.svg.append(svgEl('circle',{cx:X(m),cy:Y(sorted.find(r=>r[0]===m)[1])-8,r:5,fill:'#f5c366'}));this.output(`N = ${s.n}\n${t('Mean','माध्य')} = Σfx / N = ${fmt(s.mean)}; ${t('Median','माध्यक')} = ${fmt(s.median)}\n${t('Mode (gold dot)','बहुलक (सुनहरा बिंदु)')}: ${s.modes.map(fmt).join(', ')}`)}else this.output(`${t('Equal-width intervals','समान चौड़ाई अंतराल')}: ${sorted.map(r=>`[${r[0]}, ${r[0]+w})`).join(' ')}\nN = ${s.n}. ${t('Grouped intervals hide exact observations; exact mean, median and mode are not determined. Switch to bar chart for exact discrete statistics.','वर्गों से सटीक प्रेक्षण नहीं मिलते; सटीक माध्य, माध्यक और बहुलक निर्धारित नहीं हैं। सटीक असतत आँकड़ों के लिए दंड आलेख चुनें।')}`)}
 drawProbability(){this.clear(false);let n=this.counts.length||2,total=this.total||1,t=this.ctx.t;this.svg.append(svgEl('path',{d:'M60 40V325H550',class:'axis',fill:'none'}));for(let i=0;i<=4;i++)this.svg.append(svgEl('text',{x:20,y:329-260*i/4},String(i/4)));let y=325-260/n;this.svg.append(svgEl('line',{x1:60,x2:550,y1:y,y2:y,stroke:'#f5c366','stroke-width':2,'stroke-dasharray':'6 5'}));for(let i=0;i<n;i++){let x=85+i*460/n,f=(this.counts[i]||0)/total;this.svg.append(svgEl('rect',{x,y:325-260*f,width:320/n,height:260*f,fill:'#78d5bc'}));this.svg.append(svgEl('text',{x,y:348},n===2?(i?t('T / पूँछ','T / पूँछ'):t('H / चित','H / चित')):String(i+1)));this.svg.append(svgEl('text',{x,y:315-260*f},String(this.counts[i]||0)))}this.svg.append(svgEl('text',{x:75,y:23},'Relative frequency | सापेक्ष बारंबारता'));this.svg.append(svgEl('text',{x:190,y:380},'Outcome | परिणाम'));this.output(`${t('Throws','उछाल')}: ${this.total}; ${t('Remaining','शेष')}: ${this.pending}\n${this.total?t('Experimental probability','प्रायोगिक प्रायिकता')+' = f / N':t('No trials yet: experimental probability is undefined.','अभी कोई प्रयोग नहीं: प्रायोगिक प्रायिकता अपरिभाषित है।')}\n${t('Dotted gold line: fair-model theoretical probability','सुनहरी बिंदीदार रेखा: निष्पक्ष मॉडल की सैद्धान्तिक प्रायिकता')} = 1/${n} ≈ ${fmt(1/n)}\n${t('Finite trials need not match the theoretical value.','सीमित प्रयोगों में सैद्धान्तिक मान मिलना अनिवार्य नहीं है।')}`)}
 destroy(){cancelAnimationFrame(this.frame);super.destroy()}
}
